def f(grid):
    g=[list(map(int,row)) for row in grid]; H,W=len(g),len(g[0])
    bg=g[0][0]
    out=[row[:] for row in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and g[i][j]!=3 or True: pass
    # find anomalies: non-bg cells
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg:
                k=g[i][j]
                p=(i+j)%2
                for di in (-1,0,1):
                    ii=i+di
                    if 0<=ii<H:
                        for jj in range(W):
                            if (ii+jj)%2==p: out[ii][jj]=k
    return out
